import React, { useEffect, useState } from 'react';
import axios from 'axios';

const ShippedOrders = () => {
  const [shippedOrders, setShippedOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchShippedOrders = async () => {
      try {
        // Fetch orders from the API
        const response = await axios.get('http://localhost:5000/api/orders/confirmed-orders');
        console.log('API Response:', response.data);

        // Filter orders where the "Order Shipped" stage is completed (true)
        const shippedOrdersData = response.data.filter((order) =>
          order.status?.some((stage) => stage.stage === 'Shipped' && stage.completed === true)
        );

        // Set the filtered orders
        setShippedOrders(shippedOrdersData);
      } catch (error) {
        console.error('Error fetching shipped orders:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchShippedOrders();
  }, []);

  if (loading) return <div>Loading...</div>;

  return (
    <div className="shipped-orders-container">
      <h2>Shipped Orders</h2>
      {shippedOrders.length === 0 ? (
        <p>No shipped orders available.</p>
      ) : (
        <table className="order-table">
          <thead>
            <tr>
              <th>Order ID</th>
              <th>Product Name</th>
              <th>Delivery Type</th>
            </tr>
          </thead>
          <tbody>
            {shippedOrders.map((order, index) => (
              <tr key={index}>
                <td>{order.orderId}</td>
                <td>{order.productName}</td>
                <td>{order.deliveryType}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ShippedOrders;
